default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('PostAuthenticationActions', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_laps_postauthenticationactions_value)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS [PostAuthenticationActions]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if and (ne .Vars.win25cis_system_role "domaincontroller") .Vars.win25cis_level_1 }}
  {{ if .Vars.win25cis_rule_18_9_25_8 }}
    {{ if eq .Vars.win25cis_system_role "memberserver" }}
registry:
  HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS\PostAuthenticationActions:
    title: "18.9.25.8 | Ensure 'Post-authentication actions: Actions' is set to 'Enabled: Reset the password and logoff the managed account' or higher | PostAuthenticationActions"
    exists: true
    value: {{ .Vars.win25cis_laps_postauthenticationactions_value }}
    type: REG_DWORD
    meta:
      memberserver: 1
      server: 1
      CIS_ID:
        - 18.9.25.8
      NIST800-53R5:
        - IA-5(1)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS')) {
    New-Item -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Name 'PostAuthenticationActions' -Value $ODV_laps_postauthenticationactions_value -PropertyType DWord -Force | Out-Null
exit 0
